INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marble Racing Manager', 'Marble Racing Manager is an idle racing game where players collect and manage marbles that compete automatically. Players begin with free gems to purchase their first marble and expand their collection over time. Marbles are placed in a racing tray to enter competitions that occur automatically every 60 seconds, generating rewards without active player input. The game features an idle progression system where marbles continue racing and earning resources while the player is away.' FROM games WHERE igdb_id = 388747 ON CONFLICT (game_id, language_code) DO NOTHING;
