INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battlefield REDSEC', 'Now entering REDSEC, a free-to-play destination built on Battlefield’s iconic DNA. Drop into Fort Lyndon for a Battle Royale only Battlefield can deliver, featuring massive-scale destruction, fast-paced squad play, and the deadliest ring in BR. Survive and advance in Gauntlet: an all-new cutthroat, knockout-style elimination mode where squads race to complete missions. Then redraw the lines of battle with Portal.' FROM games WHERE igdb_id = 371393 ON CONFLICT (game_id, language_code) DO NOTHING;
