INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Total Chaos', 'Total Chaos is a relentless survival horror experience from Trigger Happy Interactive (creator of Turbo Overkill) and Apogee Entertainment. Washed ashore on Fort Oasis, a long-abandoned mining colony swallowed by decay, players must scavenge for supplies, craft makeshift weapons, and navigate a world where hallucinations warp reality and unspeakable horrors lurk in the shadows.
