INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Montezuma''s Revenge: The 40th Anniversary Edition', 'The 1983 classic multi-room platformer Montezuma’s Revenge returns in 2.5D glory, and now Pedro’s adventure is bigger than ever with 100 tricky rooms to explore! For its 40th anniversary, what was once an unfinished game is now resurrected to match the full vision of creator Robert Jaeger. This time you can choose between male and female explorers, Pedro or his sister Rosita, to delve deep into the dangerous ruins and hunt for treasures untold!' FROM games WHERE igdb_id = 330130 ON CONFLICT (game_id, language_code) DO NOTHING;
