INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MindMessenger', 'Imagine a digital escape room in which you communicate with AI characters via a familiar messenger interface - sometimes you have to outwit them, sometimes convince them or simply combine cleverly to discover new paths and hidden successes in the scenario. The advanced AI technology gives you complete freedom in your responses - no predefined dialog options, but real conversations just like in real life.' FROM games WHERE igdb_id = 342156 ON CONFLICT (game_id, language_code) DO NOTHING;
