INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Scum', 'Scum aims to evolve the multiplayer open world survival game with unprecedented levels of character customization, control and progression, where knowledge and skills are the ultimate weapons for long-term survival. Combining the methodical planning and management of hardcore survival with optional PvP ‘network events’ available to everyone at anytime, SCUM strikes a unique balance between complex simulation and intense action in the next generation of survival game.' FROM games WHERE igdb_id = 31712 ON CONFLICT (game_id, language_code) DO NOTHING;
