INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario Kart World', 'Put the pedal to the metal in a vast interconnected environment. Race seamlessly across connected courses like never before. Participate in the new knockout tour elimination mode, where you’ll barrel through back-to-back courses and checkpoints. And in free roam, it’s possible to go off the racetrack and drive in any direction you wish, explore areas that pique your interest and take some photos at scenic spots with a group of friends.' FROM games WHERE igdb_id = 338067 ON CONFLICT (game_id, language_code) DO NOTHING;
