INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tentacle Tango', 'Tentacle Tango is a quirky co-op puzzle-platformer where you and a partner must work together, tethered by a flexible tentacle. Don’t let the cute visuals fool you—this game is as challenging as it is charming. Every jump, swing, and tentacle bend requires precise coordination as you navigate puzzles, obstacles, and enemies. Whether playing solo or in local co-op, teamwork is your only path to victory, because after all, it takes two to tango!' FROM games WHERE igdb_id = 328118 ON CONFLICT (game_id, language_code) DO NOTHING;
