INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Steel Hunters', 'Steel Hunters is a Free-to-Play, PvPvE shooter with futuristic mech battles. Fight to collect rare loot on an abandoned Earth, and use combat tactics to turn rivals into scrap. Choose your Hunter and playstyle to battle 5 other duo teams. Only one can extract from the Hunting Grounds.' FROM games WHERE igdb_id = 301568 ON CONFLICT (game_id, language_code) DO NOTHING;
