INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Berrywitched! The Harvest', 'Berrywitched! The Harvest is a direct sequel to the games Berrywitched! And Cherrywitched! It is recommended you play both of those games before playing this one for the best possible experience. In this game, you follow Strawberry as she finally gets the chance to leave her pocket dimension, and uncover the truth behind why she was sent there in the first place…' FROM games WHERE igdb_id = 374169 ON CONFLICT (game_id, language_code) DO NOTHING;
