INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'S.T.A.L.K.E.R.: Call of Prypiat - Enhanced Edition', 'S.T.A.L.K.E.R.: Call of Prypiat follows the story of special service agent Major Degtyarev as he investigates the fate of a lost expedition. Rich with colorful characters, memorable side stories, and the spirit of true freedom, this chapter delivers a powerful and unforgettable conclusion to the Legends of the Zone Trilogy.' FROM games WHERE igdb_id = 343444 ON CONFLICT (game_id, language_code) DO NOTHING;
