INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Is this a Game yet?', 'Is this a Game yet? is a blank slate that players cooperatively design. Starting with just a button, you compete every week for 5 spots on a global leaderboard to have your idea implemented in the next update live on stream.' FROM games WHERE igdb_id = 353312 ON CONFLICT (game_id, language_code) DO NOTHING;
