INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Mario Party Jamboree: Nintendo Switch 2 Edition + Jamboree TV', 'Super Mario Party Jamboree is getting even more minigames and an upgrade on Nintendo Switch 2! The upgrade expands on the base game and adds Nintendo Switch 2 gameplay features, such as mouse controls, enhanced rumble, sound recognition, and modes that use a camera accessory (sold separately).' FROM games WHERE igdb_id = 338071 ON CONFLICT (game_id, language_code) DO NOTHING;
