INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Red Rogue Sea', 'Red Rogue Sea is a roguelike strategy game that puts you in the shoes of a pirate captain and their crew. Manage your vessel as you sail through the treacherous waters of the archipelago, interact with the scum that inhabit it, and engage in battle using a tactical deck-building system.' FROM games WHERE igdb_id = 338332 ON CONFLICT (game_id, language_code) DO NOTHING;
