INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rush: Apex Edition', 'RUSH: Apex Edition is a VR wingsuiting game where players dive from mountain peaks and race through canyons at high speed. Featuring remastered visuals, dynamic weather, and over 90 tracks, it offers both solo play and 12-player online races with global leaderboards and proximity chat. The game delivers an immersive, fast-paced flight experience enhanced by haptic feedback and high frame rates on PS5.' FROM games WHERE igdb_id = 375699 ON CONFLICT (game_id, language_code) DO NOTHING;
