INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jitter', 'Jitter is an immersive sci-fi exploration and survival game set on a mining colony and its outskirts in the Main Asteroid Belt. You assume the role of an experimental AI that maintains ship functions and engages with the crew on board. As you explore the mining colony, you will take on new missions, expand ships and bases using various modules, add survivors to your crew, engage in space fights, and repair the damage left by enemy fire and onboard accidents.' FROM games WHERE igdb_id = 298668 ON CONFLICT (game_id, language_code) DO NOTHING;
