INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kingdom Rush: Battles', 'Kingdom Rush: Battles is a free-to-play, real-time player-vs-player (PvP) tower defense game developed by Ironhide Game Studio. Instead of fighting against pre-set waves of enemies, players compete against each other in real-time on a split-screen map. The objective is to outlast your opponent by sending "creeps" to attack them while simultaneously building your own defenses.' FROM games WHERE igdb_id = 365682 ON CONFLICT (game_id, language_code) DO NOTHING;
