INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Laundering Simulator', 'Laundering Simulator puts you in charge of a two-faced enterprise – a laundromat as a front and a counterfeiting workshop hidden in its back. As the shady launderer, Eddie Wiser, you run this unconventional enterprise and deal with small-business management, counterfeiting, a criminal underground, nosy authorities, and a rage-inducing grandmother!' FROM games WHERE igdb_id = 332383 ON CONFLICT (game_id, language_code) DO NOTHING;
