INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tomba! 2: The Evil Swine Return Special Edition', 'Tomba! 2: The Evil Swine Return Special Edition is an action-platformer following the pink-haired hero Tomba as he confronts the return of his porcine adversaries. This updated version of the 1999 PlayStation classic combines side-scrolling platforming with RPG elements, featuring quests and item collection across a colorful world where players must defeat evil pigs and restore peace to the land.' FROM games WHERE igdb_id = 377890 ON CONFLICT (game_id, language_code) DO NOTHING;
