INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ritual of Raven', 'Ritual of Raven is a cozy farming game that lets you be creative in a witchy world by empowering you to dip your toes into the magic of coding. You will meet lots of quirky characters that you can befriend and trade with. You will be able to enchant magical creatures to help you grow the ingredients for your spells. And of course you can be creative, decorate your farm and explore the magical world around you.' FROM games WHERE igdb_id = 281390 ON CONFLICT (game_id, language_code) DO NOTHING;
