INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rune Factory: Guardians of Azuma', 'The classic action-RPG and life-simulation gameplay, beloved by Rune Factory fans across the globe, is taken in a bold new direction in Guardians of Azuma. This all-new adventure takes place in the never-before-seen eastern country of Azuma where you will assume the Earth Dancer powers and fight against the spreading Blight to bring hope back to this once-prosperous land.' FROM games WHERE igdb_id = 250922 ON CONFLICT (game_id, language_code) DO NOTHING;
