INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Paw Patrol: Rescue Wheels - Championship', 'Va-room! The Rescue Wheels crew is revved up and ready to race! Join Chase, Skye, Marshall, Rubble, Zuma, Rocky, and Roxi, in epic races across Adventure Bay and beyond. You can even cause mischief with Boomer & Frank or Mayor Humdinger. Pick your Pup Racer, each with unique skills like launching tennis balls or spinning out rivals. Master drifting, turbo boosts, and epic signature stunts to rule the dirt roads. Play solo or challenge friends in multiplayer—every racer can be a champion! Grab your best Pup Pals and let’s Rox and roll!' FROM games WHERE igdb_id = 351133 ON CONFLICT (game_id, language_code) DO NOTHING;
