INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Panzerkampf', 'Panzerkampf is a team vs team World War II and modern era tank battle game for PC. You play with historically accurate models of tanks, their armor, weapons and all their parameters. The game includes a full ballistics model with realistic calculations of penetrations and projectile ricochets, an observation/detection and surveillance system, and a physically realistic model of the motion of the tank and its wheels and tracks down to the level of individual track-links.' FROM games WHERE igdb_id = 282075 ON CONFLICT (game_id, language_code) DO NOTHING;
