INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sanatorium: A Mental Asylum Simulator', 'Set in a fictionalized version of the 1920s where the lines between modern psychiatric treatment and pseudoscience are still muddy at best. Sanatorium is a 2D card-based workplace adventure where the player has to test, diagnose and treat patients. At its core, Sanatorium is a comment on the turbulent history of the practices and pseudoscience used to stigmatize mental illnesses.' FROM games WHERE igdb_id = 213369 ON CONFLICT (game_id, language_code) DO NOTHING;
