INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bleach: Soul Resonance', 'BLEACH: Soul Resonance is a 3D action game that immerses players in thrilling sword-fighting battles. Roleplaying as Ichigo Kurosaki, players will wield their powerful Zanpakuto as they lose themselves in an original storyline while fighting alongside friends and growing stronger. The game features smooth swordplay, diverse battle strategies, and gameplay mechanics like collecting and developing multiple characters and teaming up with others for battles.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 330121 AND ge.slug = 'role-playing-rpg' ON CONFLICT DO NOTHING;
