INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gone Fishing', 'GONE Fishing is a co-op multiplayer survival horror game where you and your friends must work together to stay alive, by fishing. The only way to survive is to keep feeding the lake’s insatiable hunger before it feeds on you. Can you satisfy the hunger... or will you become the next offering?' FROM games WHERE igdb_id = 348447 ON CONFLICT (game_id, language_code) DO NOTHING;
