INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Slackjaw', 'As the latest prey of a deranged serial killer, you must use your wits and resources to survive in this atmospheric first-person escape room-style horror game. Explore, uncover secrets, and plan your escape... but be quiet, or you''ll be his next victim. Inspired by true events.' FROM games WHERE igdb_id = 355520 ON CONFLICT (game_id, language_code) DO NOTHING;
