INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Baby Steps', 'Play as Nate, an unemployed failson with nothing going for him, until one day he discovers a power he never knew he had… putting one foot in front of the other. Explore a world shrouded in mist, one step at a time. Hike the serene mountains by placing each footstep yourself, in original physics-based gameplay from the minds behind Ape Out and Getting Over It. Take in the sights, fall in love with the local fauna, and try to find meaning in a wasted life.' FROM games WHERE igdb_id = 252502 ON CONFLICT (game_id, language_code) DO NOTHING;
