INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('daemon-x-machina-titanic-scion', 250925, '2025-09-05', 76, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9mb1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar41de.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Daemon x Machina: Titanic Scion', 'From Marvelous First Studio comes an action-packed new entry in the Daemon X Machina series. Fly into battle in your customized Arsenal, unleashing a variety of attacks tailored to your playstyle. Feel the exhilaration of fast-paced combat as you freely explore a deadly and dangerous open world on land or in the air. After taking down your foes, collect their weapons and equipment, and upgrade your skills to expand your options on the battlefield. Suit up for a dark sci-fi story where you can face the titanic boss battles alone or with up to two other players online. New and veteran Daemon X Machina players alike will find a worthy adventure here.
