INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pioner', 'PIONER is an open-world MMO first-person shooter set in a haunting, alternative-reality world where Soviet-era structures lie abandoned on a desolate, post-apocalyptic island. In this immersive environment, the gameplay experience is defined by dynamic PvE and PvP elements, where realism takes priority over traditional health bars or character levels. With a sprawling map of 50+ square kilometers, not counting hidden dungeons, players can explore a world rich with mystery and danger, encountering story quests and faction missions that influence relationships and loyalty rewards.' FROM games WHERE igdb_id = 148454 ON CONFLICT (game_id, language_code) DO NOTHING;
