INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ys X: Proud Nordics', 'Stand Proud for a new adventure in Ys X: Proud Nordics! Experience Adol and Karja''s unforgettable journey across Obelia Gulf with new quality of life improvements, then discover the new story centering around Öland Island, and the mysterious newcomers Canute and Astrid. And once you''re ready, challenge yourself in the devious, time-trial dungeon of Muspelheim, where every second counts. Your new adventure awaits!' FROM games WHERE igdb_id = 326507 ON CONFLICT (game_id, language_code) DO NOTHING;
