INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sword: Depths of the Void', 'Sword: Depths of the Void is WorthyWorm and The Sword Teams first upcoming game, releasing in 2025. Sword: Depths of the Void is a 2D Action RPG Platformer with a special sword that can morph it''s blade into different weapons. Play as Trent Helms, the chosen one of this legendary sword, and make your way through various areas in open-world forms, bring people with you on your journey, explore a town in the sky, and much, much more.' FROM games WHERE igdb_id = 216193 ON CONFLICT (game_id, language_code) DO NOTHING;
