INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('captain-blood--2', 73030, '2025-05-06', 48, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9rvk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3uyu.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Captain Blood', 'Captain Blood is a pirate-themed action game set on the Spanish Main in the 17th century, where you step into the boots of a fearsome pirate on a quest for gold and glory. Expect wild adventures with cannon firing, pistol shooting, swashbuckling sword fights, and plenty of pirate shenanigans. This action-packed hack''n''slash features fierce hand-to-hand combat, hordes of enemies, and a classic fighting system with flashy combos and epic finishers.
