INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-drifter', 126870, '2025-07-17', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coabj2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar41u4.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Drifter', 'The Drifter is a 2D point-and-click adventure in the classic style. Taking cues from the recent revival of the genre there is an emphasis on story, with puzzle solving being the glue that ties it together rather than the focus. Mick''s a pretty practical guy, and so puzzles are down-to-earth, designed to be unobtrusive, and give an investigative feel. We''re keeping the pacing is quick and lean, you''ll never be wandering around lost for long periods - Mick is propelled through the story at a good clip, from one situation to another, with barely a moment to catch his breath.' FROM games WHERE igdb_id = 126870 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 126870 AND ge.slug = 'point-and-click' ON CONFLICT DO NOTHING;
