INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Agyaat', 'Agyaat is a first-person single-player horror game where you play as Acharya, drawn into the haunted depths of Ambika’s House to uncover a dark truth buried in Indian folklore. Explore, survive, and piece together the mansion’s twisted past — but beware, the house remembers every step you take.' FROM games WHERE igdb_id = 376368 ON CONFLICT (game_id, language_code) DO NOTHING;
