INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stomach', 'Stomach is a first-person survival horror cooking game located in a cruise ship with PS1 inspired graphics to capture that retro horror feeling. Your task is to read a food order, search for food ingredients, and make it back safely to the kitchen to cook your ingredients before time runs out.' FROM games WHERE igdb_id = 358750 ON CONFLICT (game_id, language_code) DO NOTHING;
