INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pathologic 3: Quarantine', 'Pathologic 3: Quarantine is a narrative-driven adventure about a young scientist in search of immortality and a mysterious plague outbreak in a small town. Learn how your story began and what drove a celebrated academic to leave his acclaimed lab. Examine patients, uncover strange secrets, and make first steps towards defeating Death.' FROM games WHERE igdb_id = 326595 ON CONFLICT (game_id, language_code) DO NOTHING;
