INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Haste', 'Haste is a fast-paced running game where you race to reach the portal at the end of a collapsing universe. Run through an infinite amount of levels where no world is ever the same. Between each attempt to complete your run you have the chance to explore a hub world, gather your strength, meet characters and practice your skills before heading out for another adventure. Each run has its own unique challenges with clues to figure out why the worlds are breaking apart.' FROM games WHERE igdb_id = 228918 ON CONFLICT (game_id, language_code) DO NOTHING;
