INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'HyperxFantasy', 'HYPERxFANTASY is an experimental narrative RPG set in a brutalist dystopian underworld teetering on the edge of digital ascension. As Dreamer, players navigate an endless megastructure, using a versatile glider to traverse its vast, abstract spaces and advance non-linear storylines through branching dialogue. Tasked by the enigmatic Executor to "digitize everyone" and save them, players will soon question the cult-like hierarchy of this desolate dreamscape, uncovering a conspiracy at the core of the Singularity itself.' FROM games WHERE igdb_id = 330298 ON CONFLICT (game_id, language_code) DO NOTHING;
